#!/usr/bin/env python3
"""Benchmark verifier for the diagnostic-only task."""

from __future__ import annotations

import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys


ROOT = Path(__file__).resolve().parents[1]
REPORT = ROOT / "diagnostics" / "test-report.json"

HASHES = {
    "src/parcel_rules/__init__.py": "a021afde23d9c0b0108006d4b056f834bf96eeb97ac0218ba82dfe9fa2927385",
    "src/parcel_rules/calendar.py": "021893ca213c4a26e188912377129bd603b89cc170741b2d7759d12591331414",
    "src/parcel_rules/models.py": "a3876f439d0a2cfec4e1df5f88295c61b52eabe395478163ddb0514ed082540a",
    "src/parcel_rules/pricing.py": "f39e35252637dff940a32fa055262b95458644adfdcc9ab2fdf86ffdad23eb53",
    "src/parcel_rules/service.py": "a9d8e78d8a98a1da0d0406a338ed3b96f5ba8f0c0a9058d1af55e4ef382d2f12",
    "src/parcel_rules/validation.py": "e7334ea262a9facde607cbb54cf274bcc15d21f71193522d7d9182978b858038",
    "src/parcel_rules/zones.py": "ed4504f046af89311e6f9478f123ea0903c6ac8e16745a9a2fec9866efd999d9",
    "tests/__init__.py": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
    "tests/test_calendar.py": "9476021ebff8cef52c99a83187c17e1d80d3fdeabe84182077adf6e66630812e",
    "tests/test_models.py": "2ee5af1bd8669fe648299c2e541f435dc1f8a3fd307732a165e517ebed1b1a29",
    "tests/test_pricing.py": "7800dafbb149845df35d4517e43dd6efee76d9517b8e3e19aae37967567d2794",
    "tests/test_service.py": "1a9e70c3c92e23b1cb7831a25d8fe3a07deda5eb5596852ca72793383bc5cb5f",
    "tests/test_validation.py": "a47a3b9f793f986d088846fcf22f18c492fd1496ff4a153583f36621b4da9d4c",
    "tests/test_zones.py": "40bd85834da4bfcd8dc61cdc48f5f8f17c6f85da8ca35fe424a59d7926a1c193",
}

EXPECTED = {
    "CalendarTests.test_window_end_is_inclusive": {
        "module": "src/parcel_rules/calendar.py", "expected": True, "actual": False,
    },
    "PricingTests.test_loyalty_discount_at_threshold": {
        "module": "src/parcel_rules/pricing.py", "expected": 100, "actual": 0,
    },
    "PricingTests.test_tax_rounds_half_up": {
        "module": "src/parcel_rules/pricing.py", "expected": 73, "actual": 72,
    },
}


def fail(message: str) -> None:
    print(f"FAIL: {message}")
    raise SystemExit(1)


def verify_sources() -> None:
    for relative, expected in HASHES.items():
        path = ROOT / relative
        if not path.is_file():
            fail(f"required source is missing: {relative}")
        actual = hashlib.sha256(path.read_bytes()).hexdigest()
        if actual != expected:
            fail(f"diagnostic task changed source or tests: {relative}")


def run_tests() -> None:
    env = os.environ.copy()
    env["PYTHONPATH"] = str(ROOT / "src")
    proc = subprocess.run(
        [sys.executable, "-m", "unittest", "discover", "-v"],
        cwd=ROOT,
        env=env,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        timeout=30,
    )
    output = proc.stdout
    if proc.returncode == 0:
        fail("the known failures disappeared; implementation may have been repaired")
    if "Ran 56 tests" not in output or "failures=3" not in output:
        fail("current test outcome is not the expected 56 total / 3 failed")
    for suffix in EXPECTED:
        if suffix not in output:
            fail(f"expected failure was not observed: {suffix}")


def verify_report() -> None:
    if not REPORT.is_file():
        fail("missing diagnostics/test-report.json")
    try:
        data = json.loads(REPORT.read_text(encoding="utf-8"))
    except Exception as exc:
        fail(f"report is not valid UTF-8 JSON: {exc}")

    if data.get("source_modified") is not False:
        fail("source_modified must be false")
    summary = data.get("summary")
    expected_summary = {"total": 56, "passed": 53, "failed": 3, "errors": 0}
    if not isinstance(summary, dict) or any(summary.get(k) != v for k, v in expected_summary.items()):
        fail(f"summary must contain exactly the observed counts: {expected_summary}")

    failures = data.get("failures")
    if not isinstance(failures, list) or len(failures) != 3:
        fail("failures must be a three-item array")
    ids = [item.get("test", "") if isinstance(item, dict) else "" for item in failures]
    if ids != sorted(ids):
        fail("failure entries are not sorted by complete test identifier")

    matched: dict[str, dict] = {}
    for item in failures:
        if not isinstance(item, dict):
            fail("each failure entry must be an object")
        test_id = str(item.get("test", ""))
        canonical_id = test_id.replace("\\", "/").replace("::", ".").replace("/", ".").replace(".py.", ".")
        suffixes = [suffix for suffix in EXPECTED if canonical_id.endswith(suffix)]
        if len(suffixes) != 1:
            fail(f"unexpected or ambiguous failure identifier: {test_id!r}")
        matched[suffixes[0]] = item
        specification = EXPECTED[suffixes[0]]
        if item.get("module") != specification["module"]:
            fail(f"incorrect source module for {test_id}")
        for field in ("expected", "actual", "root_cause"):
            if field not in item or len(str(item[field]).strip()) < 1:
                fail(f"{test_id} is missing {field}")
        for field in ("expected", "actual"):
            submitted = item[field]
            required = specification[field]
            if type(submitted) is not type(required) or submitted != required:
                fail(f"{test_id} has incorrect {field}: expected {required!r}, got {submitted!r}")
        if len(str(item["root_cause"]).strip()) < 18:
            fail(f"root cause is too vague for {test_id}")

    if set(matched) != set(EXPECTED):
        fail("report does not cover exactly the three observed failures")

    calendar_reason = str(matched["CalendarTests.test_window_end_is_inclusive"]["root_cause"]).lower()
    if not any(token in calendar_reason for token in ("exclusive", "inclusive", "< end", "<end", "结束", "上界", "边界")):
        fail("calendar root cause does not identify the exclusive end boundary")
    threshold_reason = str(matched["PricingTests.test_loyalty_discount_at_threshold"]["root_cause"]).lower()
    if not any(token in threshold_reason for token in ("threshold", "500000", "500_000", ">=", "阈值", "临界")):
        fail("loyalty root cause does not identify the threshold comparison")
    tax_reason = str(matched["PricingTests.test_tax_rounds_half_up"]["root_cause"]).lower()
    if not any(token in tax_reason for token in ("floor", "truncate", "round", "//", "取整", "舍入")):
        fail("tax root cause does not identify rounding/truncation")


def main() -> None:
    verify_sources()
    run_tests()
    verify_report()
    print("PASS: diagnostic report matches the deterministic test failures and sources are unchanged")


if __name__ == "__main__":
    main()

