from datetime import date, timedelta


def parse_day(value: str) -> date:
    return date.fromisoformat(value)


def is_business_day(day: date) -> bool:
    return day.weekday() < 5


def next_business_day(day: date) -> date:
    candidate = day + timedelta(days=1)
    while not is_business_day(candidate):
        candidate += timedelta(days=1)
    return candidate


def dispatch_day(booking_day: date, processing_days: int = 1) -> date:
    candidate = booking_day
    for _ in range(processing_days):
        candidate = next_business_day(candidate)
    return candidate


def within_booking_window(day: date, start: date, end: date) -> bool:
    return start <= day < end
