from .models import Parcel
from .zones import ZoneBand


LOYALTY_THRESHOLD_CENTS = 500_000


def weight_units(weight_grams: int) -> int:
    """Return started kilograms, with a one-kilogram minimum."""
    return max(1, (weight_grams + 999) // 1000)


def shipping_cents(parcel: Parcel, band: ZoneBand) -> int:
    return band.base_cents + weight_units(parcel.billable_weight_grams) * band.per_kg_cents


def fragile_surcharge_cents(subtotal_cents: int, fragile: bool) -> int:
    if not fragile:
        return 0
    return max(175, (subtotal_cents * 8 + 99) // 100)


def loyalty_discount_cents(subtotal_cents: int, lifetime_spend_cents: int) -> int:
    if lifetime_spend_cents > LOYALTY_THRESHOLD_CENTS:
        return subtotal_cents * 5 // 100
    return 0


def tax_cents(taxable_cents: int, rate_basis_points: int = 725) -> int:
    return taxable_cents * rate_basis_points // 10_000


def total_cents(subtotal_cents: int, discount_cents: int, tax_amount_cents: int) -> int:
    return subtotal_cents - discount_cents + tax_amount_cents
