import unittest
from datetime import date

from parcel_rules.calendar import dispatch_day, is_business_day, next_business_day, parse_day, within_booking_window


class CalendarTests(unittest.TestCase):
    def test_parse_day(self):
        self.assertEqual(parse_day("2026-04-05"), date(2026, 4, 5))

    def test_weekday(self):
        self.assertTrue(is_business_day(date(2026, 4, 6)))

    def test_weekend(self):
        self.assertFalse(is_business_day(date(2026, 4, 5)))

    def test_next_business_day_midweek(self):
        self.assertEqual(next_business_day(date(2026, 4, 7)), date(2026, 4, 8))

    def test_next_business_day_over_weekend(self):
        self.assertEqual(next_business_day(date(2026, 4, 10)), date(2026, 4, 13))

    def test_dispatch_multiple_days(self):
        self.assertEqual(dispatch_day(date(2026, 4, 9), 3), date(2026, 4, 14))

    def test_window_start_is_inclusive(self):
        self.assertTrue(within_booking_window(date(2026, 4, 1), date(2026, 4, 1), date(2026, 4, 30)))

    def test_window_end_is_inclusive(self):
        self.assertTrue(within_booking_window(date(2026, 4, 30), date(2026, 4, 1), date(2026, 4, 30)))

    def test_outside_window(self):
        self.assertFalse(within_booking_window(date(2026, 5, 1), date(2026, 4, 1), date(2026, 4, 30)))
