import unittest

from parcel_rules.models import Parcel
from parcel_rules.pricing import (
    fragile_surcharge_cents,
    loyalty_discount_cents,
    shipping_cents,
    tax_cents,
    total_cents,
    weight_units,
)
from parcel_rules.zones import ZONE_BANDS


class PricingTests(unittest.TestCase):
    def test_weight_minimum(self):
        self.assertEqual(weight_units(1), 1)

    def test_weight_exact_kilogram(self):
        self.assertEqual(weight_units(2000), 2)

    def test_weight_started_kilogram(self):
        self.assertEqual(weight_units(2001), 3)

    def test_local_shipping(self):
        self.assertEqual(shipping_cents(Parcel(1000, 1, 1, 1), ZONE_BANDS["local"]), 540)

    def test_shipping_uses_volumetric_weight(self):
        self.assertEqual(shipping_cents(Parcel(100, 20, 20, 20), ZONE_BANDS["regional"]), 930)

    def test_no_fragile_surcharge(self):
        self.assertEqual(fragile_surcharge_cents(1000, False), 0)

    def test_fragile_surcharge_minimum(self):
        self.assertEqual(fragile_surcharge_cents(1000, True), 175)

    def test_fragile_surcharge_percentage(self):
        self.assertEqual(fragile_surcharge_cents(3000, True), 240)

    def test_no_loyalty_discount_below_threshold(self):
        self.assertEqual(loyalty_discount_cents(2000, 499_999), 0)

    def test_loyalty_discount_at_threshold(self):
        self.assertEqual(loyalty_discount_cents(2000, 500_000), 100)

    def test_loyalty_discount_above_threshold(self):
        self.assertEqual(loyalty_discount_cents(2000, 500_001), 100)

    def test_tax_rounds_half_up(self):
        self.assertEqual(tax_cents(1001, 725), 73)

    def test_tax_exact(self):
        self.assertEqual(tax_cents(2000, 725), 145)

    def test_total(self):
        self.assertEqual(total_cents(2000, 100, 138), 2038)

